// WIRED 17 August 2026, task #116, Phase C.
//
// ── THE REFUND FIGURE IS THE WHOLE SCREEN ────────────────────────────────
//
// The Stitch version showed a fixed refund summary — a number nobody had
// calculated — above a Confirm button with an empty handler. The reason radios
// worked, which made it look finished.
//
// It now calls quoteStayCancellation BEFORE showing anything, so the guest
// sees what THIS cancellation returns under the terms snapshotted onto THIS
// booking. The server does the arithmetic; this screen only displays it, and
// shows the server's own explanation sentence verbatim rather than writing its
// own description of the policy.
//
// ── WHY THE FIGURE IS FETCHED AGAIN ON CONFIRM ───────────────────────────
//
// cancelStayBooking recomputes the refund rather than trusting what was
// quoted. A guest who leaves this screen open across a refund deadline would
// otherwise cancel on a stale figure. The number shown after the fact comes
// from the commit, not the preview, so what the guest is told last is what was
// actually applied.
import 'package:flutter/material.dart';
import 'package:google_fonts/google_fonts.dart';

import '../models/stay_booking.dart';
import '../models/stay_listing.dart';
import '../services/stay_booking_service.dart';
import '../services/stay_listing_service.dart';
import '../stay_routes.dart';
import '../theme/stay_colors.dart';

class CancelBookingScreen extends StatefulWidget {
  const CancelBookingScreen({super.key, required this.bookingId});

  final String bookingId;

  @override
  State<CancelBookingScreen> createState() => _CancelBookingScreenState();
}

class _CancelBookingScreenState extends State<CancelBookingScreen> {
  static const List<String> _reasons = <String>[
    'Change of plans',
    'Found somewhere else',
    'Booked by mistake',
    'Travel disruption',
    'Illness or emergency',
    'Something else',
  ];

  String _selectedReason = _reasons.first;

  StayBooking? _booking;
  StayListing? _listing;
  StayRefundQuote? _quote;
  bool _loading = true;
  String? _error;
  bool _submitting = false;

  @override
  void initState() {
    super.initState();
    _load();
  }

  Future<void> _load() async {
    try {
      final StayBooking? b =
          await StayBookingService.instance.byId(widget.bookingId);
      if (b == null) {
        if (!mounted) return;
        setState(() {
          _loading = false;
          _error = 'This booking could not be found.';
        });
        return;
      }

      // The quote and the listing together. The quote is the one that matters;
      // the listing only names the property on the card.
      final results = await Future.wait(<Future<Object?>>[
        StayBookingService.instance.quoteCancellation(widget.bookingId),
        StayListingService.instance.byId(b.listingId),
      ]);

      if (!mounted) return;
      setState(() {
        _booking = b;
        _quote = results[0] as StayRefundQuote;
        _listing = results[1] as StayListing?;
        _loading = false;
      });
    } catch (e) {
      if (!mounted) return;
      setState(() {
        _loading = false;
        // Named, not generalised. A NOT_FOUND here means
        // quoteStayCancellation is not deployed; permission-denied means
        // something else entirely, and the two need different fixes.
        _error = e.toString();
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: GoOutsColors.background,
      appBar: AppBar(
        backgroundColor: Colors.white,
        elevation: 0.5,
        leading: IconButton(
          icon: const Icon(Icons.arrow_back, color: GoOutsColors.primaryBlue),
          onPressed:
              _submitting ? null : () => Navigator.of(context).pop(),
        ),
        title: Text(
          'Cancel booking',
          style: GoogleFonts.inter(
            fontSize: 20,
            fontWeight: FontWeight.bold,
            color: GoOutsColors.deepNavy,
          ),
        ),
      ),
      body: _loading
          ? const Center(child: CircularProgressIndicator())
          : _error != null
              ? _errorBody()
              : ListView(
                  padding: const EdgeInsets.all(16),
                  children: [
                    _listingCard(),
                    const SizedBox(height: 20),
                    _sectionHeader('What you get back'),
                    _refundSummary(),
                    const SizedBox(height: 20),
                    _sectionHeader('Why are you cancelling?'),
                    _reasonList(),
                    const SizedBox(height: 16),
                    _warningCard(),
                    const SizedBox(height: 100),
                  ],
                ),
      bottomSheet:
          (_loading || _error != null) ? null : _bottomActions(),
    );
  }

  Widget _errorBody() => Center(
        child: Padding(
          padding: const EdgeInsets.all(32),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              const Icon(Icons.error_outline,
                  size: 48, color: GoOutsColors.error),
              const SizedBox(height: 12),
              Text(
                'We could not work out your refund',
                textAlign: TextAlign.center,
                style: GoogleFonts.inter(
                    fontSize: 16,
                    fontWeight: FontWeight.w600,
                    color: GoOutsColors.deepNavy),
              ),
              const SizedBox(height: 8),
              Text(
                'Nothing has been cancelled. Please try again, or contact us '
                'and we will sort it out.',
                textAlign: TextAlign.center,
                style: GoogleFonts.inter(
                    fontSize: 14, color: GoOutsColors.bodyText),
              ),
              const SizedBox(height: 12),
              Text(
                _error ?? '',
                textAlign: TextAlign.center,
                style: GoogleFonts.inter(
                    fontSize: 11.5,
                    color: GoOutsColors.bodyText.withValues(alpha: 0.8)),
              ),
            ],
          ),
        ),
      );

  Widget _sectionHeader(String title) => Padding(
        padding: const EdgeInsets.only(bottom: 10, left: 4),
        child: Text(
          title,
          style: GoogleFonts.inter(
            fontSize: 16,
            fontWeight: FontWeight.bold,
            color: GoOutsColors.deepNavy,
          ),
        ),
      );

  static const List<String> _months = <String>[
    'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
    'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec',
  ];
  static String _d(DateTime d) => '${d.day} ${_months[d.month - 1]}';

  Widget _listingCard() {
    final StayBooking b = _booking!;
    final List<StayPhoto> photos =
        List<StayPhoto>.from(_listing?.photos ?? const <StayPhoto>[])
          ..sort((a, b2) => a.order.compareTo(b2.order));

    return Container(
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(12),
      ),
      child: Row(
        children: [
          ClipRRect(
            borderRadius: BorderRadius.circular(10),
            child: photos.isEmpty
                ? Container(
                    width: 68,
                    height: 68,
                    color: GoOutsColors.paleBlueTint,
                    child: const Icon(Icons.home_outlined,
                        color: GoOutsColors.primaryBlue),
                  )
                : Image.network(photos.first.url,
                    width: 68, height: 68, fit: BoxFit.cover,
                    errorBuilder: (_, __, ___) => Container(
                          width: 68,
                          height: 68,
                          color: GoOutsColors.paleBlueTint,
                        )),
          ),
          const SizedBox(width: 12),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(_listing?.title ?? 'Your stay',
                    style: GoogleFonts.inter(
                        fontSize: 16,
                        fontWeight: FontWeight.bold,
                        color: GoOutsColors.deepNavy)),
                const SizedBox(height: 2),
                Text('${_d(b.checkIn)} to ${_d(b.checkOut)} · '
                    '${b.nights} ${b.nights == 1 ? 'night' : 'nights'}',
                    style: GoogleFonts.inter(
                        fontSize: 14, color: GoOutsColors.bodyText)),
              ],
            ),
          ),
        ],
      ),
    );
  }

  // ── Refund ───────────────────────────────────────────────────────────────

  Widget _refundSummary() {
    final StayRefundQuote q = _quote!;
    final StayBooking b = _booking!;

    return Container(
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(12),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          _row('Booking total', b.pricing.total.formatted),
          _row('Not refunded', q.nonRefundable.formatted),
          const Divider(height: 22, color: GoOutsColors.dividerGray),
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Text('Refund',
                  style: GoogleFonts.inter(
                      fontSize: 15,
                      fontWeight: FontWeight.bold,
                      color: GoOutsColors.deepNavy)),
              Text(q.refundAmount.formatted,
                  style: GoogleFonts.inter(
                      fontSize: 19,
                      fontWeight: FontWeight.w800,
                      color: GoOutsColors.tealSecondary)),
            ],
          ),
          if (q.explanation.isNotEmpty) ...[
            const SizedBox(height: 10),
            // The server's sentence, verbatim. It already accounts for the
            // grace window, the tier, unspent nights and whether anything was
            // ever paid — and rewording it here is how the screen and the
            // function start disagreeing about the same booking.
            Text(
              q.explanation,
              style: GoogleFonts.inter(
                  fontSize: 13, height: 1.4, color: GoOutsColors.bodyText),
            ),
          ],
        ],
      ),
    );
  }

  Widget _row(String label, String value) => Padding(
        padding: const EdgeInsets.symmetric(vertical: 3),
        child: Row(
          mainAxisAlignment: MainAxisAlignment.spaceBetween,
          children: [
            Text(label,
                style: GoogleFonts.inter(
                    fontSize: 14, color: GoOutsColors.bodyText)),
            Text(value,
                style: GoogleFonts.inter(
                    fontSize: 14, color: GoOutsColors.deepNavy)),
          ],
        ),
      );

  // ── Reason ───────────────────────────────────────────────────────────────

  Widget _reasonList() => Container(
        decoration: BoxDecoration(
          color: Colors.white,
          borderRadius: BorderRadius.circular(12),
        ),
        child: Column(
          children: [
            for (final r in _reasons)
              RadioListTile<String>(
                value: r,
                groupValue: _selectedReason,
                onChanged: _submitting
                    ? null
                    : (v) => setState(() => _selectedReason = v ?? r),
                activeColor: GoOutsColors.primaryBlue,
                title: Text(r,
                    style: GoogleFonts.inter(
                        fontSize: 14.5, color: GoOutsColors.deepNavy)),
                dense: true,
              ),
          ],
        ),
      );

  Widget _warningCard() => Container(
        padding: const EdgeInsets.all(14),
        decoration: BoxDecoration(
          color: GoOutsColors.errorContainer,
          borderRadius: BorderRadius.circular(12),
        ),
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const Icon(Icons.warning_amber_rounded,
                color: GoOutsColors.error, size: 20),
            const SizedBox(width: 10),
            Expanded(
              child: Text(
                'Cancelling cannot be undone. The nights go back on sale '
                'immediately and the same dates may not be available again.',
                style: GoogleFonts.inter(
                    fontSize: 13,
                    height: 1.35,
                    color: GoOutsColors.onErrorContainer),
              ),
            ),
          ],
        ),
      );

  // ── Confirm ──────────────────────────────────────────────────────────────

  Widget _bottomActions() => Container(
        padding: const EdgeInsets.fromLTRB(16, 14, 16, 28),
        decoration: const BoxDecoration(
          color: Colors.white,
          border: Border(top: BorderSide(color: GoOutsColors.dividerGray)),
        ),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            ElevatedButton(
              onPressed: _submitting ? null : _confirm,
              style: ElevatedButton.styleFrom(
                backgroundColor: GoOutsColors.error,
                disabledBackgroundColor: GoOutsColors.dividerGray,
                minimumSize: const Size(double.infinity, 52),
                shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(12)),
              ),
              child: _submitting
                  ? const SizedBox(
                      height: 20,
                      width: 20,
                      child: CircularProgressIndicator(
                          strokeWidth: 2, color: Colors.white),
                    )
                  : Text('Cancel this booking',
                      style: GoogleFonts.inter(
                          fontSize: 16,
                          fontWeight: FontWeight.bold,
                          color: Colors.white)),
            ),
            TextButton(
              onPressed:
                  _submitting ? null : () => Navigator.of(context).pop(),
              child: Text('Keep my booking',
                  style: GoogleFonts.inter(
                      fontSize: 15,
                      fontWeight: FontWeight.w600,
                      color: GoOutsColors.primaryBlue)),
            ),
          ],
        ),
      );

  Future<void> _confirm() async {
    if (_submitting) return;
    setState(() => _submitting = true);

    try {
      await StayBookingService.instance.cancel(
        bookingId: widget.bookingId,
        reason: _selectedReason,
      );
      if (!mounted) return;

      // pushReplacement: Back from the confirmation must not return to a
      // cancel screen for a booking that is already cancelled.
      Navigator.of(context).pushReplacementNamed(
        StayRoutes.cancellationDone,
        arguments: <String, dynamic>{'bookingId': widget.bookingId},
      );
    } catch (e) {
      if (!mounted) return;
      setState(() => _submitting = false);
      showDialog<void>(
        context: context,
        builder: (ctx) => AlertDialog(
          title: const Text('Not cancelled'),
          content: Text(
            'Your booking is unchanged. $e',
            style: GoogleFonts.inter(fontSize: 14, height: 1.4),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.of(ctx).pop(),
              child: const Text('Close'),
            ),
          ],
        ),
      );
    }
  }
}
